effect.shader:
vec2 pixelate(vec2 uv, float pixelSize) {
return floor(uv * pixelSize) / pixelSize;
}
float wave(vec2 uv, float freq, float amp, float time, vec2 dir) {
float x = uv.x * dir.x + uv.y * dir.y;
return sin(x * freq + time) * amp;
}
vec3 blendOverlay(vec3 base, vec3 blend) {
return mix(
2.0 * base * blend,
1.0 - 2.0 * (1.0 - base) * (1.0 - blend),
step(0.5, base)
);
}
void main() {
vec2 dir = normalize(direction);
float time = acTime * speed;
vec2 uv = acScreenNorm;
vec2 pixelUV = pixelate(uv, pixelSize);
float offset = wave(pixelUV, frequency, amplitude / 1000.0, time, dir);
vec2 distortedUV = uv + vec2(offset * dir.y, -offset * dir.x);
vec4 texColor = texture2DCv(inputImg.texture, distortedUV);
vec4 compColor = texture2DCv(comp.texture, distortedUV);
vec3 tinted = texColor.rgb * tintColor.rgb;
vec3 result;
if (blendMode == 0) {
result = mix(texColor.rgb, tinted, tintColor.a);
} else if (blendMode == 1) {
result = texColor.rgb * mix(vec3(1.0), tintColor.rgb, tintColor.a);
} else if (blendMode == 2) {
result = 1.0 - (1.0 - texColor.rgb) * (1.0 - mix(vec3(0.0), tintColor.rgb, tintColor.a));
} else {
result = mix(texColor.rgb, blendOverlay(texColor.rgb, tintColor.rgb), tintColor.a);
}
gl_FragColor = mix(texColor, vec4(result, texColor.a), alpha);
}
